package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Marks the claim just added a late entry when the period containing its date is soft-closed, recorded as
 * LATE_ENTRY; nothing otherwise.
 */
public class MarkLateEntry {
    public void mark(@Val Claim claim, @Val Person person, @RequestParam("user") String user,
            PeriodRepository periods, ClaimRepository claims, Audit audit) {
        mark(claim, person, user, periods, claims, audit, true);
    }

    /** Marks the claim when its period is soft-closed; shared with the paste. */
    public static void mark(Claim claim, Person person, String user, PeriodRepository periods, ClaimRepository claims,
            Audit audit, boolean unused) {
        if (periods.softClosedOn(claim.sheetId(), claim.date()) == null) {
            return;
        }
        claims.markLateEntry(claim);
        audit.record("LATE_ENTRY sheet=" + claim.sheetId() + " by=" + user + " person=" + person.name()
                + " amount=" + claim.amount().setScale(2).toPlainString() + " date=" + claim.date());
    }
}
EOF

